package com.ftk.tpip.control.application.integration;

import com.fasterxml.jackson.databind.JsonNode;import com.ftk.tpip.control.application.provider.CanonicalJsonService;import com.ftk.tpip.policy.compiler.DefaultPolicyCompiler;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Component;
@Component public class PolicyContentCanonicalizer{private static final int MAX=1024*1024;private final CanonicalJsonService json;public PolicyContentCanonicalizer(CanonicalJsonService json){this.json=json;}public String schema(JsonNode value){if(value==null||!value.isObject())throw new IllegalArgumentException("configurationSchema must be an object");DefaultPolicyCompiler.validateConfigurationSchema(value);return bounded(json.canonicalString(value),"configurationSchema");}public String document(JsonNode value){if(value==null||!value.isObject())throw new IllegalArgumentException("policy document must be an object");return bounded(json.canonicalString(value),"policy document");}public String checksum(String value){return json.sha256(value);}private static String bounded(String v,String f){if(v.getBytes(StandardCharsets.UTF_8).length>MAX)throw new IllegalArgumentException(f+" exceeds "+MAX+" bytes");return v;}}
